export async function operationProofV66(M,entry,op,role,h){if(!names.includes(entry.raw.name))return false;let n=0;const assert={ok:(...a)=>{strict.ok(...a);n++;},equal:(...a)=>{strict.equal(...a);n++;},deepEqual:(...a)=>{strict.deepEqual(...a);n++;}};for(const positive of [true,false])await proveCommonV66(M,entry.raw.name,role,positive,h,assert);return n;}
